 "content": "from collections import deque


def transform(grid):
    """Color centers of solid 3x3 windows according to their 4-connected region."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    component = [[-1] * w for _ in range(h)]
    colors = {}
    cid = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or component[r][c] != -1:
                continue
            q = deque([(r, c)])
            component[r][c] = cid
            found = set()
            while q:
                y, x = q.popleft()
                if grid[y][x] != 1:
                    found.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and component[ny][nx] == -1:
                        component[ny][nx] = cid
                        q.append((ny, nx))
            if found:
                colors[cid] = min(found)
            cid += 1

    # A marker colors the centers of each complete 3x3 patch in its region.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            cells = [(y, x) for y in range(r - 1, r + 2) for x in range(c - 1, c + 2)]
            if any(grid[y][x] == 0 for y, x in cells):
                continue
            ids = {component[y][x] for y, x in cells}
            if len(ids) != 1:
                continue
            color = colors.get(next(iter(ids)))
            if color is not None:
                out[r][c] = color
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
